const ALL = ["FRED", "Finnhub", "AlphaVantage", "TwelveData", "MarketAux", "GNews"];
const body = $json.body || $json || {};
let sources = body.sources !== undefined ? body.sources : (body.source || 'all');
if (sources === 'all' || sources === true || sources == null) sources = ALL.slice();
else if (typeof sources === 'string') sources = sources.split(',').map(s => s.trim()).filter(Boolean);
else if (!Array.isArray(sources)) sources = ALL.slice();
sources = sources.filter(s => ALL.includes(s));
if (!sources.length) sources = ALL.slice();
return [{ json: { sources, requested_at: new Date().toISOString(), mode: 'phase2-keyed-stubs' } }];

const ALL = ["FRED", "Finnhub", "AlphaVantage", "TwelveData", "MarketAux", "GNews"];
const requested = ($('Normalize Sources').first().json.sources) || ALL;
const out = { ok: true, phase: 2, requested_at: $('Normalize Sources').first().json.requested_at,
  sources_requested: requested, results: {}, errors: {}, note: 'keys may be REPLACE_ME placeholders' };
function trimVal(v) {
  if (Array.isArray(v)) return { truncated: true, count: v.length, sample: v.slice(0, 3) };
  if (v && typeof v === 'object') {
    const keys = Object.keys(v);
    if (keys.length > 40) {
      const sample = {}; for (const k of keys.slice(0, 20)) sample[k] = v[k];
      return { truncated: true, key_count: keys.length, sample };
    }
  }
  return v;
}
for (const name of ALL) {
  if (!requested.includes(name)) { out.results[name] = { skipped: true }; continue; }
  try {
    const item = $(name).first(); const j = item ? item.json : null;
    if (j && (j.error || j.message) && (j.statusCode || j.status || j.error)) {
      out.errors[name] = { message: j.message || j.error, status: j.statusCode || j.status };
      out.results[name] = { error: true };
    } else { out.results[name] = trimVal(j); }
  } catch (e) {
    out.errors[name] = { message: String(e.message || e) };
    out.results[name] = { error: true };
  }
}
return [{ json: out }];

const res = $input.first().json.results || {};
const items = [];

// 1. MarketAux articles & entity sentiment
const ma = res.MarketAux;
if (ma && !ma.skipped && !ma.error && Array.isArray(ma.data)) {
  for (const art of ma.data.slice(0, 10)) {
    const scores = [];
    if (Array.isArray(art.entities)) {
      for (const ent of art.entities) {
        if (ent.symbol && typeof ent.sentiment_score === 'number') {
          const sent = ent.sentiment_score > 0.05 ? 'bullish' : ent.sentiment_score < -0.05 ? 'bearish' : 'neutral';
          scores.push({
            pair: ent.symbol,
            sentiment: sent,
            score: ent.sentiment_score,
            confidence: (ent.match_score || 50) / 100,
            reasoning: art.snippet ? art.snippet.substring(0, 150) : '',
            model: 'marketaux'
          });

          items.push({
            json: {
              type: 'sentiment',
              endpoint: 'http://backend:8000/api/news/sentiment',
              payload: {
                symbol: ent.symbol.replace(/[^a-zA-Z0-9]/g, ''),
                sentiment_score: Math.round(ent.sentiment_score * 100) / 100,
                impact_score: 0.7,
                source: 'marketaux',
                time_horizon: 'medium',
                topics: ent.industry || 'equities'
              }
            }
          });
        }
      }
    }

    items.push({
      json: {
        type: 'article',
        endpoint: 'http://backend:8000/api/sentiment/ingest',
        payload: {
          source: 'marketaux',
          external_id: art.uuid || art.url,
          title: art.title,
          description: art.description || art.snippet || art.title,
          url: art.url,
          published_at: art.published_at || new Date().toISOString(),
          scores: scores.length > 0 ? scores : undefined,
          auto_score: scores.length === 0
        }
      }
    });
  }
}

// 2. FRED Macro Indicators
const fred = res.FRED;
if (fred && !fred.skipped && !fred.error) {
  const obs = fred.observations || fred.data || [];
  if (Array.isArray(obs) && obs.length > 0) {
    const latest = obs[obs.length - 1];
    items.push({
      json: {
        type: 'calendar',
        endpoint: 'http://backend:8000/api/calendar/batch',
        payload: {
          events: [{
            time_utc: latest.date ? new Date(latest.date).toISOString() : new Date().toISOString(),
            currency: 'USD',
            impact: 'HIGH',
            title: 'FRED Economic Indicator Observation',
            actual: String(latest.value || ''),
            source: 'fred'
          }]
        }
      }
    });
  }
}

return items.length > 0 ? items : [{ json: { type: 'empty' } }];
